  const access = await getReviewAccess(request.headers);
  if (access.status !== "available") return new Response(null, { status: 401 });

  return Response.json(
    {
      profile: {
        name: access.profile.name?.fullName || access.profile.primaryEmail,
        email: access.profile.primaryEmail,
        image: access.profile.thumbnailPhotoUrl,
      },
    },
    { headers: { "Cache-Control": "no-store" } },
  );
}

